export const FINGERPRINT_DEVICE_LABELS = Object.freeze(Object.fromEntries(Object.entries(rows).map(([locale, values]) => [locale, Object.freeze(Object.fromEntries(FINGERPRINT_DEVICE_KEYS.map((key, index) => [key, values[index]])))])));
export function fingerprintDeviceLabels(locale) {
  const key = typeof locale === 'string' ? locale : typeof locale?.id === 'string' ? locale.id : 'en';
  return FINGERPRINT_DEVICE_LABELS[key] ?? FINGERPRINT_DEVICE_LABELS[key.replace('-', '_')] ?? FINGERPRINT_DEVICE_LABELS[key.split(/[-_]/u)[0]] ?? FINGERPRINT_DEVICE_LABELS.en;
}
